use ingetrazo_gui::app::IngeTrazoApp;use ingetrazo_core::{composition::{Sheet,SheetItem,ViewFrame,RectMm},math::Ray};use ingetrazo_tools::base::{ToolContext,ToolType};use glam::DVec3;use serde_json::json;
struct Harness{app:IngeTrazoApp,dir:std::path::PathBuf}
impl eframe::App for Harness{fn update(&mut self,ctx:&egui::Context,_:&mut eframe::Frame){
if ctx.input(|i|i.key_pressed(egui::Key::F2)){self.app.scene.active_sheet_index=Some(1);}
if ctx.input(|i|i.modifiers.ctrl&&i.key_pressed(egui::Key::Z)){self.app.undo();}
if ctx.input(|i|i.modifiers.ctrl&&i.key_pressed(egui::Key::Y)){self.app.redo();}
let mut buttons=serde_json::Map::new();egui::TopBottomPanel::top("acceptance-actions").show(ctx,|ui|{ui.horizontal(|ui|{
for(label,index)in [("Sheet 1",Some(0)),("Sheet 2",Some(1)),("Model",None)]{let r=ui.button(label);buttons.insert(label.into(),json!([r.rect.center().x,r.rect.center().y]));if r.clicked(){self.app.finish_composer_edit();self.app.scene.active_sheet_index=index;}}
let r=ui.button("Extrude");buttons.insert("Extrude".into(),json!([r.rect.center().x,r.rect.center().y]));if r.clicked(){self.app.set_tool(ToolType::PushPull);let pick=ToolContext::new(DVec3::new(0.5,0.5,0.),Ray::new(DVec3::new(0.5,0.5,5.),-DVec3::Z));self.app.dispatch_tool_click(&pick);self.app.dispatch_tool_vcb(".2").unwrap();}
});});
let mut click=egui::Pos2::ZERO;egui::CentralPanel::default().frame(egui::Frame::none()).show(ctx,|ui|{let r=ui.max_rect();if let Some(index)=self.app.scene.active_sheet_index{let (w,h)=self.app.scene.sheets[index].dimensions_mm();let zoom=self.app.composer_state.zoom;let item=self.app.scene.sheets[index].items[0].rect();click=r.center()-egui::vec2(w as f32*zoom/2.,h as f32*zoom/2.)+egui::vec2((item.x+item.w/2.)as f32*zoom,(item.y+item.h/2.)as f32*zoom);ingetrazo_gui::composer::render_sheet_composer(&mut self.app,ui,index);}else{ui.label("Model context");}});
let sheets=self.app.scene.sheets.iter().map(|s|{let history=self.app.composer_state.sheet_history.get(&s.id);json!({"rect":s.items[0].rect(),"undo":history.map(|h|h.0.len()).unwrap_or(0),"redo":history.map(|h|h.1.len()).unwrap_or(0)})}).collect::<Vec<_>>();
let data=json!({"active":self.app.scene.active_sheet_index,"sheets":sheets,"model_faces":self.app.scene.mesh.faces.len(),"model_undo":self.app.undo_stack.len(),"model_redo":self.app.redo_stack.len(),"drag":self.app.composer_state.dragging_item_idx,"pending":self.app.composer_state.edit_before.is_some(),"click":[click.x,click.y],"buttons":buttons});
std::fs::write(self.dir.join("state.tmp"),serde_json::to_vec(&data).unwrap()).unwrap();std::fs::rename(self.dir.join("state.tmp"),self.dir.join("state.json")).unwrap();
if let Ok(name)=std::fs::read_to_string(self.dir.join("capture.txt")){let _=std::fs::remove_file(self.dir.join("capture.txt"));ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(egui::UserData::new(name)));}
for e in ctx.input(|i|i.events.clone()){if let egui::Event::Screenshot{image,user_data,..}=e{let data=user_data.data.unwrap();let name=data.downcast_ref::<String>().unwrap();let pixels:Vec<u8>=image.pixels.iter().flat_map(|p|p.to_array()).collect();image::save_buffer(self.dir.join(format!("{name}.png")),&pixels,image.size[0]as u32,image.size[1]as u32,image::ColorType::Rgba8).unwrap();}}
ctx.request_repaint_after(std::time::Duration::from_millis(30));}}
fn main()->eframe::Result{let dir=std::env::args().nth(1).unwrap().into();let mut app=IngeTrazoApp::new();let ids=[DVec3::ZERO,DVec3::X,DVec3::new(1.,1.,0.),DVec3::Y].map(|p|app.scene.mesh.add_vertex(p));app.scene.mesh.add_face(ids.to_vec(),vec![]).unwrap();app.scene.sheets=(0..2).map(|i|{let mut s=Sheet::default();s.name=format!("Sheet {i}");let mut f=ViewFrame::default();f.rect=RectMm::new(40.,50.,100.,60.);f.style="vectorial".into();s.items=vec![SheetItem::ViewFrame(f)];s}).collect();app.scene.active_sheet_index=Some(0);
eframe::run_native("Independent Composer History",eframe::NativeOptions{viewport:egui::ViewportBuilder::default().with_inner_size([1000.,800.]),..Default::default()},Box::new(move |_|Ok(Box::new(Harness{app,dir}))))}
